import{d as c,C as t,o as m,c as u,j as a,a as r,E as o,a3 as b}from"./chunks/framework.Q4yG9rk_.js";const _=JSON.parse('{"title":"道德经第七十九章","description":"从大怨余伤读守契防怨，依王注辨司契、司彻及天道无亲。","frontmatter":{"title":"道德经第七十九章","description":"从大怨余伤读守契防怨，依王注辨司契、司彻及天道无亲。","category":"guide","aliases":["道德经第七十九章","老子第七十九章","dao de jing chapter 79"],"source":["王弼《道德真经注》卷四"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-79.md","filePath":"daoism/dao-de-jing/chapter-79.md","lastUpdated":1794189804000}'),p={name:"daoism/dao-de-jing/chapter-79.md"},y=c({...p,setup(g){const n=[{id:"great-resentment-and-lingering-hurt",label:"和大怨，必有余怨",showLabel:!0,sentences:[[{text:"和",glossary:"he-harmony"},"大怨，必有余怨；安可以为善？"]],note:["【白话】调和深重的仇怨，必然还会留下残余怨恨；怎么能把这样才来补救当作妥善的做法呢？发问把注意力从事后平息引向怨如何形成。","【王弼注择要】「已至而德以和之，其伤不复，故必有余怨也。」","【读法】伤不复说明大怨造成的伤损未必能恢复，不能因表面和解就当作没有受损；这不等于否定必要的和解与修复。"]},{id:"holding-the-left-tally",label:"是以圣人执左契",showLabel:!0,sentences:[["是以圣人执",{text:"左契",glossary:"zuoqi"},"，而不",{text:"责",glossary:"ze-demand"},"于人。"]],note:["【白话】所以圣人持有契约的左半作为凭据，却不拿它向人逼索。持有约据，并不以尽量责取他人为目标。","【王弼注择要】「左契，防怨之所由生也。」","【读法】契券分持用以为信，左右执掌在不同解释中有分歧。本页不硬套固定的现代债权人身份，依王注把重心放在守约、防怨。"]},{id:"virtue-attends-to-the-agreement",label:"有德司契",showLabel:!0,sentences:[["有德",{text:"司",glossary:"si-attend"},{text:"契",glossary:"qi-agreement"},"，"]],note:["【白话】有德的人用心于审守约契，使怨不致发生。这里的司，是掌管并把心力放在其上。","【王弼注择要】「有德之人念思其契，不令怨生而后责于人也。」","【读法】注句连读为不令怨生而后责于人，重在防止形成怨后再追责的局面；不把而后单独截成鼓励先压住怨气、再向人索取。"]},{id:"fault-finding-without-virtue",label:"无德司彻",showLabel:!0,sentences:[["无德",{text:"司",glossary:"si-attend"},{text:"彻",glossary:"che-inspect-faults"},"。"]],note:["【白话】无德的人则专门察究他人的过失。这是依本页所据王注作出的解释，与司契的防怨方向对照。","【王弼注择要】「彻，司人之过也。」","【读法】彻另有古代税制的解释路向，但王注在此明确落在人的过失。本页采用王注训释，不将征税说混成王弼原义。"]},{id:"heaven-without-private-favor",label:"天道无亲，常与善人",showLabel:!0,sentences:[[{text:"天道",glossary:"tiandao"},"无",{text:"亲",glossary:"qin-draw-close"},"，常",{text:"与",glossary:"yu-associate"},"善人。"]],note:["【白话】天之道没有偏私的亲厚对象，却常常相助善人。末句同时说无私亲与向善，不能只截其中半句。","【读法】与取帮助、赞助义。所据末句未另见独立王注，保留古代天道观念；现代伦理与现实遭遇需分别判断，不保证行善者立即顺遂，更不能据遭难倒推其不善。"]}],s=[{id:"he-harmony",term:"和",sense:2},{id:"zuoqi",term:"左契",sense:1},{id:"ze-demand",term:"责",sense:1},{id:"si-attend",term:"司",sense:1},{id:"qi-agreement",term:"契",sense:1},{id:"che-inspect-faults",term:"彻",sense:1},{id:"tiandao",term:"天道",sense:1},{id:"qin-draw-close",term:"亲",sense:2},{id:"yu-associate",term:"与",sense:3}];return(x,e)=>{const i=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return m(),u("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第七十九章",tabindex:"-1"},[r("道德经第七十九章 "),a("a",{class:"header-anchor",href:"#道德经第七十九章","aria-label":'Permalink to "道德经第七十九章"'},"​")],-1)),o(i,{title:"和解之后仍有余怨，怎样回到怨的源头",summary:"本章先说大怨即使调和，也会留下余怨，再把理想治理者的用心转到执契而不逼索。王注以不令怨生说明司契，以司人之过说明司彻。末句以天道无私亲而与善人收束，不能把它改写成现实善恶报应的即时保证。",points:[{label:"先读",text:"先读和解之后仍有余伤，不把它误作反对一切和解。"},{label:"再辨",text:"执左契、不责于人连读，再看司契与司彻的方向差别。"},{label:"后看",text:"天道无亲与常与善人合读，辨无私与向善的关系。"}],hint:"契读 qì，责读 zé，司读 sī，彻读 chè；与读 yǔ，此处取相助义。彻本页依王注作察过解释。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[r("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),o(l,{sections:n,glossary:s}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[r("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),o(d,{lines:[{text:"和大怨，必有余怨；安可以为善？",tone:"不把和解视为归零",guide:"已经造成的伤损，可能仍留在关系里。"},{text:"是以圣人执左契，而不责于人。",tone:"有凭据也不尽量逼索",guide:"重心是怎样防怨，而非怎样占尽可索之利。"},{text:"有德司契，无德司彻。",tone:"辨用心方向",guide:"依王注，一面防怨，一面察人的过失。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[r("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),o(h,{items:s}),e[4]||(e[4]=b('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-既能和解-为什么仍说不能算善" tabindex="-1">象：既能和解，为什么仍说不能算善？ <a class="header-anchor" href="#象-既能和解-为什么仍说不能算善" aria-label="Permalink to &quot;象：既能和解，为什么仍说不能算善？&quot;">​</a></h3><p>王注提醒其伤不复：争怨造成的损伤不会因为达成和解便自动消失。本章因此追问能否在怨未形成时审守约契，不能只以事后平息证明处理得好。</p><h3 id="理-司契和司彻的分界在哪里" tabindex="-1">理：司契和司彻的分界在哪里？ <a class="header-anchor" href="#理-司契和司彻的分界在哪里" aria-label="Permalink to &quot;理：司契和司彻的分界在哪里？&quot;">​</a></h3><p>依本页所据注，前者念思其契、防止生怨，后者专司人的过失。分界在用心何处，而不是用有没有书面凭据来判定德行，也不等于取消所有合理追责。</p><h3 id="用-今天怎样避免只在事后查过" tabindex="-1">用：今天怎样避免只在事后查过？ <a class="header-anchor" href="#用-今天怎样避免只在事后查过" aria-label="Permalink to &quot;用：今天怎样避免只在事后查过？&quot;">​</a></h3><p>尽早说明双方承诺、边界与调整办法，让问题能够在损伤扩大前被提出。已经发生的伤害仍应修复、承担责任，不能借不责于人要求受损者放弃权益。</p><h2 id="【解读层】现代解读与启发" tabindex="-1">【解读层】现代解读与启发 <a class="header-anchor" href="#【解读层】现代解读与启发" aria-label="Permalink to &quot;【解读层】现代解读与启发&quot;">​</a></h2><p><strong>把争议条件提前说清。</strong> 约定不只是留下追责证据，也应帮助双方确认责任、能力和变化时的协商路径，减少含混期待积累成怨。</p><p><strong>让修复承认余伤。</strong> 达成协议后仍留出恢复与复核的时间；不以已经和解为由要求所有人立刻忘记，也不把持续受伤归咎于不够宽容。</p><h2 id="【个人记录】我的笔记" tabindex="-1">【个人记录】我的笔记 <a class="header-anchor" href="#【个人记录】我的笔记" aria-label="Permalink to &quot;【个人记录】我的笔记&quot;">​</a></h2><p>留给自己的续读问题：我维护约定，是为了减少怨的发生，还是为了事后证明别人有错？和解之后，还有哪些实际损伤没有得到照顾？</p><h2 id="校读说明与参考来源" tabindex="-1">校读说明与参考来源 <a class="header-anchor" href="#校读说明与参考来源" aria-label="Permalink to &quot;校读说明与参考来源&quot;">​</a></h2><ul><li>正文与古注据卷四 010b–011a 电子录文核对。</li><li>正文、标点、别名沿本站保留，注语据所列卷页核对。</li><li>彻按司人之过解释，税制解仅注明另一路向；左契不武断固定为现代债权方身份。</li><li>不令怨生而后责于人也保留连文说明，不截句导向事后逼索。天道末句未补造独立王注。</li><li>古注节引转简体并加标点，尚未逐字核对影印；白话、古注与现代启发分层。</li></ul><p>参考：<a href="https://github.com/kanripo/KR5c0073/blob/b988441bd55861741c850e1dff4a2d4f895daf3d/KR5c0073_004.txt" target="_blank" rel="noreferrer">王弼《道德真经注》卷四 HFL 本电子录文，010b–011a</a>。</p>',15))])}}});export{_ as __pageData,y as default};
